// Render only inside the tactics popup; there is no match-tick work here.
var supportMapVisible=true;
function supportMapSvg(d){return '<svg class="support-map" viewBox="0 0 100 100" preserveAspectRatio="none" aria-hidden="true">'+d.shape.links.map(p=>'<line x1="'+p.x1+'" y1="'+p.y1+'" x2="'+p.x2+'" y2="'+p.y2+'" class="'+p.chemistry.tier+(p.selected?' selected':'')+'"/>').join('')+'</svg>'+d.shape.links.map(p=>'<span class="support-link-label '+p.chemistry.tier+(p.selected?' selected':'')+'" style="left:'+((p.x1+p.x2)/2)+'%;top:'+((p.y1+p.y2)/2)+'%" aria-hidden="true">'+p.chemistry.score+'</span>').join('');}
function touchlineMarkup(d){
 const selected=d.shape.selected,labels={tactics:'배치와 역할 확인',roster:'선발·교체 검토',analysis:'전술 지표 비교',talk:'선수 대화 열기'};
 return '<div class="support-summary"><strong>선수 능력과 패스 궁합</strong><p>선발 종합 평균 '+d.team.overall+' · 체력 평균 '+d.team.energy+'</p><div class="chemistry-legend"><span class="strong">80↑ 잘 맞음</span><span class="good">65↑ 무난함</span><span class="caution">65 미만 조율 필요</span></div><span>필드 배치 폭 '+Math.round(d.shape.width)+' · 깊이 '+Math.round(d.shape.depth)+' · 가까운 동료 없는 선수 '+d.shape.isolated.length+'명</span>'+(selected?'<p>'+escapeText(selected.name)+' · 종합 '+selected.overall+' · 체력 '+Math.round(selected.energy)+'<br>'+escapeText(selected.roleName)+' · 적합도 '+Math.round(selected.roleFit)+' · 주변 동료 '+selected.count+'명 · 앞쪽 지원 '+selected.forward+'명</p><ul>'+selected.nearby.map(p=>'<li><b>'+escapeText(p.name)+'</b> · 궁합 '+p.chemistry.score+' '+p.chemistry.label+' · 거리 '+Math.round(p.distance)+'<small>패스 '+Math.round(p.chemistry.parts.passing)+' / 팀워크 '+Math.round(p.chemistry.parts.teamwork)+' / 역할 '+Math.round(p.chemistry.parts.role)+' / 체력 '+Math.round(p.chemistry.parts.condition)+'</small></li>').join('')+'</ul>':'<p>선수를 선택하면 가까운 동료와 앞쪽 지원 위치를 확인할 수 있습니다.</p>')+'<small>'+escapeText(d.assumption)+'</small></div><details class="touchline-briefing"><summary>수석 코치 작전 브리핑 · '+d.minute+'분</summary><p>'+(d.minute?'최근 '+d.recent.from+'–'+d.recent.to+'분 확정된 경기 이벤트':'킥오프 전 · 실제 경기 이벤트는 아직 없습니다.')+'</p><div class="touchline-facts"><span>슈팅 <b>'+d.recent.shots.join(' : ')+'</b></span><span>득점 <b>'+d.recent.goals.join(' : ')+'</b></span><span>교체 여유 <b>'+d.remainingSubs+'회</b></span></div><small>슈팅·득점은 우리 : 상대 순서입니다. 브리핑은 현재 상태를 읽으며 경기를 진행하지 않습니다.</small><div class="touchline-advice">'+d.suggestions.map(p=>'<article><h4>'+escapeText(p.title)+'</h4><p>'+escapeText(p.text)+'</p><button type="button" class="secondary" data-match-popup="'+p.action+'">'+labels[p.action]+'</button></article>').join('')+'</div></details>';
}
